@layer components {
  @media (pointer: coarse) {
    :where([data-control-family="button"][data-size="xs"]) {
      position: relative;
    }

    :where([data-control-family="button"][data-size="xs"])::after {
      content: "";
      position: absolute;
      inset: 50% 50%;
      translate: -50% -50%;
      inline-size: 100%;
      block-size: max(100%, 44px);
    }
  }

  :where(
    [data-control-family="popup"][data-popup-kind="dialog"][data-slot="content"]
      > [data-control-family="button"][data-popup-part="close"][data-icon-only="true"]
  ) {
    position: absolute;
    top: 12px;
    right: 12px;
  }
  :where([data-control-family="button"][data-control="true"]) {
    --cui-button-radius: var(--radius-control);
    --cui-button-gap: calc(var(--spacing) * 1.5);
    --cui-button-icon: 1rem;
    --cui-button-height: var(--control-h-md);
    --cui-button-padding-inline: var(--padding-x);
    --cui-button-icon-padding-inline: max(0px, calc(var(--cui-button-padding-inline) - var(--spacing) * 0.5));
    --cui-button-font-size: var(--text-body);
    --cui-button-background: transparent;
    --cui-button-background-image: none;
    --cui-button-foreground: var(--muted-foreground);
    --cui-button-hover-background: var(--hover-fill);
    --cui-button-hover-foreground: var(--foreground);
    --cui-button-press-background: var(--cui-button-hover-background);
    --cui-button-press-scale: 0.98;
    --cui-button-active-background: var(--active-fill);
    --cui-button-active-foreground: var(--foreground);
    --cui-button-active-hover-background: var(--cui-button-active-background);
    --cui-button-active-shadow: var(--cui-button-shadow);
    --cui-button-shadow: 0 0 transparent;
    --cui-button-hover-shadow: var(--cui-button-shadow);
    --cui-button-press-shadow: var(--cui-button-hover-shadow);
    --cui-button-open-background: var(--cui-button-hover-background);
    --cui-button-open-foreground: var(--cui-button-hover-foreground);
    --cui-button-open-shadow: var(--cui-button-shadow);
    border-radius: var(--cui-button-radius);
    background-color: var(--cui-button-background);
    background-image: var(--cui-button-background-image);
    box-shadow: var(--cui-button-shadow);
    color: var(--cui-button-foreground);
    cursor: pointer;
    font-weight: var(--font-weight-medium);
    outline: none;
    transition-property: scale, translate;
    transition-timing-function: var(--ease-standard);
    transition-duration: var(--duration-fast);
  }

  :where([data-control-family="button"]) {
    gap: var(--cui-button-gap);
  }

  :where([data-control-family="button"][data-size="xs"]) {
    --cui-button-gap: calc(var(--spacing) * 1);
    --cui-button-icon: 0.875rem;
    --cui-button-height: var(--control-h-xs);
    --cui-button-padding-inline: calc(var(--padding-x) * 0.6);
    --cui-button-font-size: var(--text-caption);
  }
  :where([data-control-family="button"][data-size="sm"]) {
    --cui-button-height: var(--control-h-sm);
    --cui-button-padding-inline: calc(var(--padding-x) * 0.75);
    --cui-button-font-size: var(--text-label);
  }
  :where([data-control-family="button"][data-size="lg"]) {
    --cui-button-gap: calc(var(--spacing) * 2);
    --cui-button-icon: 1.125rem;
    --cui-button-height: var(--control-h-lg);
    --cui-button-padding-inline: calc(var(--padding-x) * 1.25);
  }

  :where([data-control-family="button"][data-size]) {
    block-size: var(--cui-button-height);
    padding-inline: var(--cui-button-padding-inline);
    font-size: var(--cui-button-font-size);
  }

  :where(
    [data-control-family="button"][data-control="true"][data-size]:not([data-icon-only="true"]):has(
      > :is(svg, [data-slot="icon"]):first-child:not(:only-child),
      > [data-slot="content"] > :is(svg, [data-slot="icon"]):first-child:not(:only-child)
    )
  ) {
    padding-inline-start: var(--cui-button-icon-padding-inline);
  }

  :where(
    [data-control-family="button"][data-control="true"][data-size]:not([data-icon-only="true"]):has(
      > :is(svg, [data-slot="icon"]):last-child:not(:only-child),
      > [data-slot="content"] > :is(svg, [data-slot="icon"]):last-child:not(:only-child)
    )
  ) {
    padding-inline-end: var(--cui-button-icon-padding-inline);
  }

  :where([data-control-family="button"][data-icon-only="true"]) {
    aspect-ratio: 1;
    padding-inline: 0;
  }

  :where([data-control-family="button"][data-control="true"] svg) {
    pointer-events: none;
    flex-shrink: 0;
    width: var(--cui-button-icon);
    height: var(--cui-button-icon);
  }

  :where([data-control-family="button"][data-cursor="default"]) {
    cursor: default;
  }

  :where([data-control-family="button"][data-variant="ghost"]) {
    --cui-button-foreground: var(--foreground);
    --cui-button-active-background: transparent;
    --cui-button-active-foreground: var(--foreground);
    --cui-button-active-hover-background: var(--cui-button-hover-background);
  }

  :where([data-control-family="button"][data-variant="solid"]) {
    --cui-button-background: var(--primary);
    --cui-button-foreground: var(--primary-foreground);
    --cui-button-hover-background: oklch(from var(--primary) l c h / 0.9);
    --cui-button-hover-foreground: var(--primary-foreground);
    --cui-button-shadow: var(--shadow-sm);
    --cui-button-active-background: var(--cui-button-background);
    --cui-button-active-foreground: var(--cui-button-foreground);
    --cui-button-active-hover-background: var(--cui-button-hover-background);
  }

  :where([data-control-family="button"][data-variant="surface"]) {
    --cui-button-background: oklch(from var(--card) l c h / 0.72);
    --cui-button-foreground: var(--foreground);
    --cui-button-hover-background: oklch(from var(--foreground) l c h / 0.05);
    --cui-button-hover-foreground: var(--foreground);
    --cui-button-shadow: inset 0 0 0 var(--control-rim-width) var(--control-rim), var(--shadow-sm);
    --cui-button-active-background: oklch(from var(--primary) l c h / 0.08);
    --cui-button-active-foreground: var(--primary-text);
    --cui-button-active-shadow: inset 0 0 0 1px oklch(from var(--primary) l c h / 0.6), var(--shadow-sm);
    --cui-button-active-hover-background: oklch(from var(--primary) l c h / 0.1);
  }

  :where([data-control-family="button"]:is([data-variant="surface"], [data-variant="ghost"], [data-variant="quiet"])) {
    --cui-button-open-background: oklch(from var(--foreground) l c h / 0.07);
  }

  :where([data-control-family="button"][data-tone="primary"]:not([data-variant="solid"])) {
    --cui-button-foreground: var(--primary-text);
    --cui-button-hover-foreground: var(--primary-text);
  }

  :where([data-control-family="button"][data-tone="danger"][data-variant="solid"]) {
    --cui-button-background: var(--destructive);
    --cui-button-foreground: var(--destructive-foreground);
    --cui-button-hover-background: oklch(from var(--destructive) l c h / 0.9);
    --cui-button-hover-foreground: var(--destructive-foreground);
    --cui-button-active-background: var(--cui-button-background);
    --cui-button-active-foreground: var(--cui-button-foreground);
    --cui-button-active-hover-background: var(--cui-button-hover-background);
  }

  :where([data-control-family="button"][data-tone="danger"]:not([data-variant="solid"])) {
    --cui-button-foreground: var(--destructive-text);
    --cui-button-hover-foreground: var(--destructive-text);
  }

  :where([data-control-family="button"][data-shape="circle"]) {
    --cui-button-radius: 9999px;
  }

  @media (hover: hover) {
    :where([data-control-family="button"][data-control="true"]:hover) {
      background-color: var(--cui-button-hover-background);
      box-shadow: var(--cui-button-hover-shadow);
      color: var(--cui-button-hover-foreground);
    }
  }

  :where([data-control-family="button"][data-popup-open]) {
    background-color: var(--cui-button-open-background);
    color: var(--cui-button-open-foreground);
    box-shadow: var(--cui-button-open-shadow);
  }

  :where([data-control-family="button"][data-active="true"]) {
    background-color: var(--cui-button-active-background);
    box-shadow: var(--cui-button-active-shadow);
    color: var(--cui-button-active-foreground);
  }

  @media (hover: hover) {
    :where([data-control-family="button"][data-active="true"]:hover) {
      background-color: var(--cui-button-active-hover-background);
      color: var(--cui-button-active-foreground);
    }
  }

  @scope ([data-track="hover"]) to ([data-track]) {
    @media (hover: hover) {
      :where(
          [data-track="hover"] [data-control-family="button"][data-track-item]:hover:not([data-active="true"], [data-popup-open], :active)
        ) {
        background-color: var(--cui-button-background);
        box-shadow: var(--cui-button-shadow);
      }

      :where(
          [data-track="hover"] [data-control-family="button"][data-track-item][data-active="true"]:hover:not([data-popup-open], :active)
        ) {
        background-color: var(--cui-button-active-background);
      }
    }
  }

  @scope ([data-track="slide"]) to ([data-track]) {
    :where([data-track="slide"] [data-control-family="button"][data-track-item]:not([data-popup-open], :active)) {
      background-color: var(--cui-button-background);
      box-shadow: var(--cui-button-shadow);
    }
  }

  :where([data-control-family="button"][data-control="true"]:active) {
    background-color: var(--cui-button-press-background);
    box-shadow: var(--cui-button-press-shadow);
    scale: var(--cui-button-press-scale);
  }

  :where([data-control-family="button"]:is(:disabled, [data-disabled], [aria-disabled="true"])) {
    cursor: not-allowed;
    opacity: 0.45;
  }

  :where([data-control-family="button"][data-button-kind="model-switcher"][data-slot="value"]) {
    gap: calc(var(--spacing) * 1.5);
  }

  :where([data-control-family="button"][data-slot="group"]) {
    gap: calc(var(--spacing) * 1);
  }
}

